<?php
$title='API Usage & Costs';$subtitle='Every API Setu can use – status, free limits, usage and estimated cost';
$C=Usage::catalog();
if(is_post()&&($_POST['a']??'')==='ai_prices'){
  $pu=jd(setting('price_update'));
  if(($pu['status']??'')==='running'&&strtotime($pu['at'])>time()-600)flash('A price check is already running.','warn');
  else{Settings::set('price_update',je(['status'=>'running','msg'=>'Queued – starting in a few seconds…','at'=>date('Y-m-d H:i:s')]));DB::q("DELETE FROM jobs WHERE type='prices' AND status='pending'");Queue::push('prices',0);Cron::spawn();flash('Price check started – the AI is looking up current prices and free limits. This takes 1–3 minutes; you can keep working.');}
  redirect(url('usage'));}
if(is_post()){
  $o=jd(setting('usage_prices'));
  foreach(($_POST['svc']??[]) as $k=>$x)if(isset($C[$k]))$o[$k]=['price'=>max(0,(float)($x['price']??0)),'free'=>max(0,(float)($x['free']??0))];
  foreach(($_POST['mdl']??[]) as $k=>$x){$k=trim($k);if($k!==''&&($x['in']!==''||$x['out']!==''))$o['_models'][$k]=['in'=>max(0,(float)$x['in']),'out'=>max(0,(float)$x['out'])];}
  if(($n=trim($_POST['new_model']??''))!=='')$o['_models'][$n]=['in'=>max(0,(float)($_POST['new_in']??0)),'out'=>max(0,(float)($_POST['new_out']??0))];
  Settings::set('usage_prices',je($o));
  Settings::set('fx_mode',($_POST['fx_mode']??'auto')==='manual'?'manual':'auto');
  if(($_POST['usd_rate']??'')!=='')Settings::set('usd_rate',max(0.0001,(float)$_POST['usd_rate']));
  flash('Prices and limits saved.');redirect(url('usage'));}
$M=Usage::month();$P=Usage::prices();$D=Usage::daily(30);
[$rate,$fxm,$fxat]=Usage::fx();$cur=setting('currency','INR');$sym=setting('currency_symbol','₹');
$lc=fn($usd)=>$cur==='USD'?'$'.number_format($usd,2):$sym.number_format($usd*$rate,$usd*$rate<100?2:0);
$usd=fn($v)=>'$'.number_format($v,$v<10?2:0);
$groups=['Maps & website data'=>['google_places','google_places_details','google_places_ids','google_places_atmo','google_places_details_atmo','serpapi','pagespeed'],'AI writing'=>['anthropic','web_search','openai','openrouter','gemini','groq','deepseek','custom'],'Messaging'=>['email','whatsapp','whatsapp_api'],'AI voice calls'=>['voice_sarvam','voice_bland','voice_vapi','voice_retell','voice_custom'],'Calendar'=>['gcal']];
$rows=[];$tc=0;$tp=0;$calls=0;$warn=[];
foreach($groups as $g=>$ks)foreach($ks as $k){if(!isset($C[$k]))continue;$c=$C[$k];$m=$M[$k]??null;$price=(float)($P[$k]['price']??$c[3]);$free=(float)($P[$k]['free']??$c[4]);[$b,$bp]=Usage::bill($k,$m,$price,$free);$tc+=$b;$tp+=$bp;$calls+=$m['calls']??0;if($m&&$free>0&&$m['proj']>$free)$warn[]=$c[0];$rows[$g][]=[$k,$c,$m,$price,$free,$b,$bp,Usage::status($k)];}
$fmt=fn($c,$m)=>!$m?'<span class="muted">0</span>':($c[2]==='tokens'?number_format($m['in']/1000,1).'k in · '.number_format($m['out']/1000,1).'k out':number_format($m['units'],$c[2]==='minutes'?1:0).' <small class="muted">'.$c[2].'</small>');
// 30-day chart
$days=[];for($i=29;$i>=0;$i--){$d=date('Y-m-d',strtotime("-$i day"));$days[$d]=['c'=>(float)($D[$d]['cost']??0),'n'=>(int)($D[$d]['calls']??0)];}
$mx=max(0.01,max(array_column($days,'c')));$mn=max(1,max(array_column($days,'n')));$W=900;$H=170;$bw=$W/30;
$svg='<svg class="chart" viewBox="0 0 '.$W.' '.($H+26).'" role="img" aria-label="Daily API usage, last 30 days">';
foreach([0,.5,1] as $g){$y=$H-$g*$H+2;$svg.='<line x1="0" x2="'.$W.'" y1="'.$y.'" y2="'.$y.'" stroke="#EEF0F5"/><text x="2" y="'.($y-4).'" font-size="10" fill="#98A0B3">'.e($usd($mx*$g)).'</text>';}
$i=0;$pts=[];foreach($days as $d=>$v){$h=$v['c']/$mx*($H-14);$x=$i*$bw+4;$svg.='<rect x="'.round($x,1).'" y="'.round($H-$h+2,1).'" width="'.round($bw-8,1).'" height="'.round(max($h,$v['c']>0?2:0),1).'" rx="4" fill="url(#ug)"><title>'.e(date('d M',strtotime($d)).': '.$usd($v['c']).' · '.$v['n'].' calls').'</title></rect>';$pts[]=round($x+($bw-8)/2,1).','.round($H-$v['n']/$mn*($H-14)+2,1);if($i%5===0||$i===29)$svg.='<text x="'.round($x+($bw-8)/2,1).'" y="'.($H+18).'" font-size="10.5" fill="#98A0B3" text-anchor="middle">'.date('d M',strtotime($d)).'</text>';$i++;}
$svg.='<polyline points="'.implode(' ',$pts).'" fill="none" stroke="#F97316" stroke-width="2" stroke-linejoin="round" opacity=".85"/><defs><linearGradient id="ug" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#8B5CF6"/><stop offset="1" stop-color="#6366F1"/></linearGradient></defs></svg>';
$gi=['Maps & website data'=>['map','orange'],'AI writing'=>['spark','violet'],'Messaging'=>['msg','green'],'AI voice calls'=>['mic','pink'],'Calendar'=>['cal','teal']];
$sn=0;
?>
<div class="stats"><?=kpi('Estimated bill this month',$lc($tc),'activity','violet',$usd($tc).' after free tiers')?><?=kpi('Projected by month end',$lc($tp),'target','blue',$usd($tp).' at the current pace')?><?=kpi('API calls this month',number_format($calls),'zap','teal',count($M).' services used in '.date('F'))?><?=kpi('Free limits at risk',count($warn),'alert',$warn?'rose':'green',$warn?'<span>'.e(implode(', ',$warn)).'</span>':'all within free limits')?></div>
<?php if($warn):?><div class="al al-warn"><?=icon('alert')?><span><b>Heads-up:</b> at the current pace you will go over the free limit for <?=e(implode(', ',$warn))?> this month.</span></div><?php endif?>
<?php $inuse=[];foreach($rows as $g=>$list)foreach($list as $r)if($r[2]||$r[7][1]==='green')$inuse[]=$r+[8=>$g];?>
<div class="card-h"><h3><span class="hi c-blue"><?=icon('activity')?></span>Services in use</h3><span class="muted sm"><?=date('F Y')?> · resets on the 1st</span></div>
<?php if(!$inuse):?><div class="card"><div class="empty sm"><?=icon('activity')?><p>No API is connected or used yet.</p></div></div><?php else:?><div class="ug"><?php foreach($inuse as [$k,$c,$m,$price,$free,$b,$bp,[$stl,$stc],$g]):[$gic,$gcl]=$gi[$g];$tok=$c[2]==='tokens';$used=$m?($c[5]==='day'?$m['used']:$m['units']):0;$pc=$free>0?min(100,round($used/$free*100)):null;?><div class="card uc c-<?=$gcl?>"><div class="uc-h"><span class="hi"><?=icon($gic)?></span><div class="grow"><b><?=e($c[0])?></b><small><?=e($g)?></small></div><span class="bdg c-<?=$stc?>"><?=e($stl)?></span></div><div class="uc-v"><b><?=$tok?($m?number_format(($m['in']+$m['out'])/1000,1).'k':'0'):number_format($used,$c[2]==='minutes'?1:0)?></b><span><?=$tok?'tokens':e($c[2])?><?=$c[5]==='day'?' today':' this month'?></span></div><?php if($pc!==null):?><div class="pb <?=$pc>=100?'r':($pc>=75?'a':'g')?>"><i style="width:<?=$pc?>%"></i></div><small class="pbm"><?=$pc?>% of <?=number_format($free)?> free / <?=$c[5]?></small><?php else:?><small class="pbm"><?=$tok?'Billed per token':($price?'No free tier':'Free')?></small><?php endif?><div class="uc-f"><span>Est. cost <b><?=$lc($b)?></b></span><span>Projected <b><?=$lc($bp)?></b></span></div></div><?php endforeach?></div><?php endif?>
<div class="card mt"><div class="card-h"><h3><span class="hi c-violet"><?=icon('activity')?></span>Daily cost &amp; calls – last 30 days</h3><div class="row sm muted"><span class="row nw" style="gap:6px"><i style="width:10px;height:10px;border-radius:3px;background:#7C5CF0;display:inline-block"></i>Cost (USD)</span><span class="row nw" style="gap:6px"><i style="width:14px;height:2px;background:#F97316;display:inline-block"></i>Calls</span></div></div><?=$svg?></div>
<?php $pu=jd(setting('price_update'));$run=($pu['status']??'')==='running'&&strtotime($pu['at']??'')>time()-600;$web=setting('ai_provider','anthropic')==='anthropic';?><div class="card"><div class="pu"><span class="hi c-violet"><?=icon('spark')?></span><div class="grow"><b>Update prices &amp; free limits with AI</b><small class="muted" style="display:block"><?=$web?'Claude searches the providers\' official pricing pages and updates only values that changed.':'Your AI provider cannot search the web – prices come from the model\'s knowledge. Use Claude for live prices.'?><?=!empty($pu['at'])&&!$run?' Last check: '.ago($pu['at']).'.':''?></small></div><form method="post"><?=csrf_field()?><input type="hidden" name="a" value="ai_prices"><button class="btn btn-p" <?=$run?'disabled':''?>><?php if($run):?><span class="spin"></span>Checking prices…<?php else:?><?=icon('refresh')?>Update with AI<?php endif?></button></form></div><?php if(!empty($pu['status'])):?><div class="al al-<?=['running'=>'info','done'=>'ok','error'=>'err'][$pu['status']]??'info'?> mt mb0" id="pu-s"><?=icon($pu['status']==='error'?'alert':'check')?><span><b><?=e($pu['msg']??'')?></b><?php if(!empty($pu['changes'])):?><ul class="pu-l"><?php foreach($pu['changes'] as $x):?><li><?=e($x)?></li><?php endforeach?></ul><?php endif?></span></div><?php endif?></div>
<?php if($run):?><script>(function p(){setTimeout(function(){fetch('index.php?r=api&do=prices',{credentials:'same-origin'}).then(function(r){return r.json()}).then(function(s){if(s.status&&s.status!=='running')location.reload();else p()}).catch(p)},4000)})()</script><?php endif?>
<div class="card p0"><div class="card-h"><h3><span class="hi c-teal"><?=icon('list')?></span>All APIs</h3><span class="muted sm">Status, free limit and price used for estimates</span></div><div class="tw"><table class="tbl"><thead><tr><th class="sn">#</th><th>API</th><th>Status</th><th class="num">Used</th><th class="num">Free limit</th><th class="num">Price (USD)</th><th class="num">Est. cost</th></tr></thead><tbody><?php $sn=0;foreach($rows as $g=>$list):foreach($list as [$k,$c,$m,$price,$free,$b,$bp,[$stl,$stc]]):$sn++;$tok=$c[2]==='tokens';?><tr><td class="sn"><?=$sn?></td><td class="biz" style="min-width:230px"><b><?=e($c[0])?></b><small><?=e($g)?><?=$c[6]?' · <a class="lnk" href="'.e($c[6]).'" target="_blank" rel="noopener">pricing</a>':''?></small></td><td><span class="bdg c-<?=$stc?>"><?=e($stl)?></span></td><td class="num nowrap"><?=$fmt($c,$m)?></td><td class="num nowrap"><?=$tok?'—':($free>0?number_format($free).' / '.$c[5]:'—')?></td><td class="num nowrap"><?=$tok?'per model':($price>0?'$'.rtrim(rtrim(number_format($price,4),'0'),'.').' / '.e((['searches'=>'search','calls'=>'call','requests'=>'request','messages'=>'message','minutes'=>'minute','emails'=>'email'][$c[2]]??$c[2])):'Free')?></td><td class="num nowrap"><b><?=$lc($b)?></b></td></tr><?php endforeach;endforeach?></tbody></table></div></div>
<form method="post"><?=csrf_field()?><details class="opt"><summary><span class="hi c-orange"><?=icon('edit')?></span>Edit free limits, prices &amp; currency</summary>
<div class="tw mt"><table class="tbl"><thead><tr><th>API</th><th>Free units</th><th>USD per unit</th></tr></thead><tbody><?php foreach($rows as $g=>$list)foreach($list as [$k,$c,$m,$price,$free]):if($c[2]==='tokens')continue;?><tr><td><b><?=e($c[0])?></b><br><small class="muted">per <?=e((['searches'=>'search','calls'=>'call','requests'=>'request','messages'=>'message','minutes'=>'minute','emails'=>'email'][$c[2]]??$c[2]))?> · free limit resets every <?=$c[5]?></small></td><td><input type="number" min="0" step="1" name="svc[<?=$k?>][free]" value="<?=e($free+0)?>" style="width:130px;margin:0"></td><td><input type="number" min="0" step="0.0001" name="svc[<?=$k?>][price]" value="<?=e($price+0)?>" style="width:130px;margin:0"></td></tr><?php endforeach?></tbody></table></div>
<h4 id="models">AI model prices (USD per 1 million tokens)</h4><div class="tw"><table class="tbl"><thead><tr><th>Model</th><th>Input</th><th>Output</th></tr></thead><tbody><?php foreach($P['_models'] as $k=>$x):?><tr><td><code><?=e($k)?></code><?=$k===AI::model()?' <span class="bdg c-green sm">in use</span>':''?></td><td><input type="number" step="0.001" min="0" name="mdl[<?=e($k)?>][in]" value="<?=e($x['in'])?>" style="width:110px;margin:0"></td><td><input type="number" step="0.001" min="0" name="mdl[<?=e($k)?>][out]" value="<?=e($x['out'])?>" style="width:110px;margin:0"></td></tr><?php endforeach?><tr><td><input name="new_model" placeholder="Add model id" style="margin:0"></td><td><input type="number" step="0.001" min="0" name="new_in" style="width:110px;margin:0"></td><td><input type="number" step="0.001" min="0" name="new_out" style="width:110px;margin:0"></td></tr></tbody></table></div>
<?php if($cur!=='USD'):?><h4>Currency</h4><div class="fg"><label>Rate source<select name="fx_mode" data-toggle><option value="auto" <?=$fxm!=='manual'?'selected':''?>>Automatic – free exchange-rate API, refreshed daily (now 1 USD = <?=$sym.number_format($rate,2)?>)</option><option value="manual" <?=$fxm==='manual'?'selected':''?>>Manual – I enter the rate</option></select></label><label data-show="fx_mode=manual">1 USD in <?=e($cur)?><input type="number" step="0.0001" name="usd_rate" value="<?=e(setting('usd_rate','84'))?>"></label></div><?php endif?>
